document.addEventListener('toggle',event=>{if(!event.target.matches?.('.executive-measure'))return;const key=event.target.dataset.measureKey;if(event.target.open)collapsedExecutiveMeasures.delete(key);else collapsedExecutiveMeasures.add(key);},true);
