 renderMethodSummary();$('generate-method').disabled=!ready||busy||!!executiveErrors.length;
 $('copy-executive').disabled=!ready||busy||!!executiveErrors.length;$('generate-executive').disabled=busy||!selectedEpics().length;$('generate-executive').innerHTML=icon('ai','violet')+(busy?'Generating…':'Generate summary');
