 if(!ready){$('executive-content').innerHTML=executiveScope===currentExecutiveScope()?executiveInspection():'';$('executive-status').textContent=executiveScope===currentExecutiveScope()?'No supported executive updates are ready. Review generation details or retry.':'Generate copy-ready program updates by measure and team.';return;}
 const count=executiveRows.filter(executiveReady).length,unready=executiveRows.length-count+executiveBlocked.length+executiveErrors.length;$('executive-status').textContent=`${count} updates ready${unready?' · '+unready+' need review':''}`;
