 $('executive-content').innerHTML=executiveGroups().map(g=>executiveMeasureHTML(g.measure,g.teams.map(team=>`<article class="executive-team"><h4>${esc(fullExecutiveTeam(team.team))}</h4>${[...team.epics].sort((a,b)=>statusOrder(a.health)-statusOrder(b.health)).map(row=>`<div class="executive-epic-update" data-epic-id="${esc(row.epicId)}"><p class="executive-blurb">${esc(row.blurb)}</p></div>`).join('')}</article>`).join(''))).join('')+executiveInspection();
