 el.innerHTML=methodError?`<div class="note warning" role="alert">${esc(methodError)} Your epic summaries remain available below.</div>`:`<section class="method-summary-card"><div class="method-summary-heading"><h3>Consolidated Measure Updates</h3><button class="button small" id="copy-method">Copy measure updates</button></div><p class="method-summary-note">${esc(monthLabel(state.review))} · ${methodRows.every(r=>r.mode==='sdk')?'GUS Apps AI':'AI updates with clearly labeled source summaries'} · Review before sharing</p>${[...new Set(methodRows.map(r=>measureIdentity(r.measure)))].map(key=>{const rows=methodRows.filter(r=>measureIdentity(r.measure)===key);return executiveMeasureHTML(rows[0].measure,rows.map(r=>`<article class="method-team-update"><h4>${esc(fullExecutiveTeam(r.team))}</h4>${r.mode==='sdk'?`<p>${esc(r.blurb)}</p>`:`<details class="executive-inspection"><summary>Review generation details</summary><p>${esc(r.error)}</p>${r.rejected?`<p>${esc(r.rejected)}</p>`:''}</details>`}</article>`).join(''),'method');}).join('')}</section>`;
