async function generateMethodSummary(){if(methodBusy||state.executiveGenerating||executiveErrors.length||executiveScope!==currentExecutiveScope()||!executiveRows.length)return;
 const scope=currentExecutiveScope(),month=state.review,groups=executiveGroups().flatMap(g=>g.teams.map(t=>({measure:g.measure,team:t.team,rows:t.epics.map(row=>({...row,measure:g.measure}))}))),results=[],usageResults=[];methodBusy=true;methodError='';methodScope=scope;methodRows=[];let completed=0;methodProgress=`Consolidating teams: 0 of ${groups.length} complete`;renderExecutive();
 try{await Promise.all(groups.map(g=>background.add('method:'+JSON.stringify([scope,g.measure,g.team]),async()=>{let rejected='';try{const result=await ReviewAI.complete(ReviewAI.methodPayload(g.rows,month));rejected=result.aiRejectedDraft||'';usageResults.push(result);if(result.mode!=='sdk'||!result.blurb)throw Error(result.aiNotice||'AI did not return a complete method update.');results.push({measure:g.measure,team:g.team,blurb:result.blurb,mode:'sdk'});}catch(error){results.push({measure:g.measure,team:g.team,mode:'source',error:error.message,rejected,sources:g.rows});}finally{completed++;methodProgress=`Consolidating teams: ${completed} of ${groups.length} complete`;renderExecutive();}})));methodRows=results.sort((a,b)=>a.measure.localeCompare(b.measure)||a.team.localeCompare(b.team));
 }catch(error){methodRows=[];methodError=error.message;}finally{methodBusy=false;renderExecutive();showAIUsage('V2MOM consolidated summary',usageResults);}
}
